import{Log as FrameworkLog,TopMostLayer as FrameworkTopMostLayer}from"Beckhoff.TwinCAT.HMI.Framework/index.esm.js";let frameworkCore={log:FrameworkLog,topMostLayer:FrameworkTopMostLayer};export function setFrameworkCore(api){frameworkCore=api}export function getFrameworkCore(){if(frameworkCore)return frameworkCore;throw new Error("Helper framework core is not initialized. Call setFrameworkCore() during startup.")}export const Log={error(message,forceNoPrefix){getFrameworkCore().log.error(message,forceNoPrefix)},errorEx(message,...optionalParameters){getFrameworkCore().log.errorEx(message,...optionalParameters)},warn(message,forceNoPrefix){getFrameworkCore().log.warn(message,forceNoPrefix)},warnEx(message,...optionalParameters){getFrameworkCore().log.warnEx(message,...optionalParameters)},info(message,forceNoPrefix){getFrameworkCore().log.info(message,forceNoPrefix)},infoEx(message,...optionalParameters){getFrameworkCore().log.infoEx(message,...optionalParameters)}};export const TopMostLayer={addEx(element){getFrameworkCore().topMostLayer.addEx(element)},removeEx(element){getFrameworkCore().topMostLayer.removeEx(element)}};